class MyApp extends StatefulWidget{@override _MyAppState createState()=>_MyAppState();}
class _MyAppState extends State<MyApp>{Uint8List? image;void renderPdf() async{String path=await FilePicker.getFilePath(type:FileType.custom,allowedExtensions:['pdf']);final pdf=PdfImageRenderer(path:path);await pdf.open();await pdf.openPage(pageIndex:0);final size=await pdf.getPageSize(pageIndex:0);final img=await pdf.renderPage(pageIndex:0,x:0,y:0,width:size.width,height:size.height,scale:1,background:Colors.white);await pdf.closePage(pageIndex:0);pdf.close();setState(()=>image=img);}
@override Widget build(BuildContext context){return MaterialApp(home:Scaffold(appBar:AppBar(title:Text('pdf_image_renderer')),body:Center(child:image!=null?Image(image:MemoryImage(image!)):Text('Loading...'))));}}
